import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    s = input_data[1]
    t = input_data[2]

    if s.count('1') != t.count('1'):
        print(-1)
        return

    diff = []
    for i in range(n):
        if s[i] != t[i]:
            diff.append((i, s[i], t[i]))

    if not diff:
        print(0)
        return

    cnt1 = 0
    cnt0 = 0

    for _, s_char, t_char in diff:
        if s_char == '1':
            cnt1 += 1
        else:
            cnt0 += 1

    ans = max(cnt1, cnt0)
    print(ans)

if __name__ == "__main__":
    solve()
